#!/usr/bin/env python3
"""Apply the revision edits to a copy of MS_final_reviewed.docx as tracked, purple insertions with a comment on each.
Usage: python3 apply_manuscript_edits.py <unpacked_dir>      (the directory is edited in place)
Every number comes from ms_numbers.load(); nothing is typed in by hand.
"""
import sys
sys.path.insert(0, "/private/tmp/claude-501/-Users-kizie-Library-Mobile-Documents-com-apple-CloudDocs-OneDrive-UJ-Sonata2-mdfs-combine-taxonomy-and-functions-CRC-segata-pooling-framework-repository/6551195e-d5c2-48ab-8e21-ed987b4c0792/scratchpad/ms_edit")
from docx_edit import Doc
import ms_numbers
from ms_numbers import sp, fmt

N = ms_numbers.load()
WORDS = {0: 'no', 1: 'one', 2: 'two', 3: 'three', 4: 'four', 5: 'five', 6: 'six', 7: 'seven', 8: 'eight', 9: 'nine', 10: 'ten', 11: 'eleven', 12: 'twelve', 13: 'thirteen'}
word = lambda n: WORDS.get(n, str(n))
d = Doc(sys.argv[1])
import os
d.dry = os.environ.get("DRY") == "1"
AI = "[AI edit] "
NOTVER = " I did not verify this against the literature; please check."


def R(anchor, old, new, why):
    d.replace(d.one(anchor), old, new, AI + why)


def P(anchor, new, why):
    i = d.one(anchor); d.replace(i, d.text(i), new, AI + why)


def I(anchor, text, why, **kw):
    return d.insert_after(d.one(anchor), text, AI + why, **kw)


def C(anchor, why, old=None):
    d.comment(d.one(anchor), AI + why, old)


r5 = N["r5"]
def r5get(prefix):
    for k, v in r5.items():
        if k.startswith(prefix):
            return v
    return None

